import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    resp = requests.get(url, timeout=5)
    content = resp.content if resp.content is not None else b""

    if len(content) == 0:
        return {}

    enc = from_encoding
    if enc is None:
        detected = chardet.detect(content)
        enc = detected.get("encoding") if isinstance(detected, dict) else None

    if not enc:
        raise ValueError("Unable to detect encoding for non-empty content")

    text = content.decode(enc)
    recoded = text.encode(to_encoding)
    final_text = recoded.decode(to_encoding).lstrip("\ufeff")
    return json.loads(final_text)

