import ast
import json
from collections import Counter
def task_func(file_pointer):
    try:
        if hasattr(file_pointer, 'seek'):
            file_pointer.seek(0)
        data = json.load(file_pointer)
    except Exception:
        return Counter()

    key_counts = Counter()

    items = [data] if isinstance(data, dict) else data
    for item in items:
        current = item
        if isinstance(item, str):
            try:
                current = ast.literal_eval(item)
            except (ValueError, SyntaxError):
                continue
        if isinstance(current, dict):
            key_counts.update(current.keys())

    return key_counts

