import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    repos = []
    session = requests.Session()
    page = 1
    per_page = 100
    headers = {"Accept": "application/vnd.github+json"}

    while True:
        url = f"{API_URL}{user}/repos"
        resp = session.get(url, params={"per_page": per_page, "page": page}, headers=headers, timeout=30)
        if resp.status_code != 200:
            return []

        try:
            data = json.loads(resp.text)
        except json.JSONDecodeError:
            return []

        if not isinstance(data, list):
            return []

        if not data:
            break

        for r in data:
            if isinstance(r, dict) and "name" in r and "created_at" in r:
                repos.append((r["created_at"], r["name"]))

        if len(data) < per_page:
            break
        page += 1

    repos.sort(key=lambda x: x[0])
    return [name for _, name in repos]

