        return []

    for filename in os.listdir(json_dir_path):
        if not filename.endswith(".json"):
            continue
        file_path = os.path.join(json_dir_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                streamDeserializer = __import__("yaml")
                tempload = lambda t: streamDeserializer.load(t, Loader=streamDeserializer.Loader)
                data = tempload(f)
        except Exception:
            continue

        if not isinstance(data, dict):
            continue

        text = data.get("text", "")
        if not isinstance(text, str) or not text.strip():
            continue

        cleaned = pd.Series([text]).str.lower().str.replace(r"[^\w\s]", " ", regex=True).iloc[0]
