HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    import matplotlib.pyplot as plt

    if not isinstance(url, str) or not url.strip() or not (url.startswith("http://") or url.startswith("https://")):
        raise Exception("Invalid url")

    try:
        resp = requests.get(url, headers=HEADERS, params=parameters, timeout=30)
        resp.raise_for_status()
    except Exception as e:
        raise Exception("url cannot be accessed") from e

    try:
        payload = json.loads(resp.text)
    except Exception as e:
        raise Exception("invalid data") from e

    if isinstance(payload, dict) and "data" in payload:
        records = payload["data"]
    else:
        records = payload

    if records is None or records == {} or records == []:
        raise Exception("empty data")

    if isinstance(records, dict):
        records = [records]

    if not isinstance(records, list) or not all(isinstance(r, dict) for r in records):
        raise Exception("invalid data")

    df = pd.DataFrame(records)
    if df.empty:
        raise Exception("empty data")

    num_df = df.select_dtypes(include="number")
    if num_df.shape[1] == 0:
        raise Exception("invalid data")

    corr = num_df.corr(numeric_only=True)
    if corr.empty:
        raise Exception("invalid data")

