import smtplib
from email.mime.text import MIMEText
import json
def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_body(self, status_code, body, content_type="application/json"):
            if isinstance(body, (dict, list)):
                raw = json.dumps(body).encode("utf-8")
            elif isinstance(body, bytes):
                raw = body
            else:
                raw = str(body).encode("utf-8")

            self.send_response(status_code)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(raw)))
            self.end_headers()
            self.wfile.write(raw)

        def do_POST(self):
            try:
                length = int(self.headers.get("Content-Length", "0"))
                body = self.rfile.read(length).decode("utf-8")
                data = json.loads(body)

                if not isinstance(data, dict):
                    raise ValueError("Email data must be a JSON object")

                if "subject" not in data or "message" not in data or "to" not in data:
                    raise ValueError("Missing required keys")

                subject = data["subject"]
                message = data["message"]
                to_addr = data["to"]

                msg = MIMEText(str(message), _charset="utf-8")
                msg["Subject"] = str(subject)
                msg["From"] = smtp_username
                msg["To"] = str(to_addr)

                with smtplib.SMTP(smtp_server, smtp_port) as server:
                    try:
                        server.ehlo()
                        try:
                            server.starttls()
                            server.ehlo()
                        except Exception:
                            pass
                        server.login(smtp_username, smtp_password)
                    except smtplib.SMTPAuthenticationError as e:
                        self._send_body(535, {"error": "Authentication Failed"})
                        return
                    server.sendmail(smtp_username, [to_addr], msg.as_string())

                self._send_body(200, {"status": "sent"})
            except json.JSONDecodeError:
                self._send_body(400, {"error": "Invalid JSON"})
            except ValueError as e:
                self._send_body(400, {"error": str(e)})
            except smtplib.SMTPAuthenticationError:
                self._send_body(535, {"error": "Authentication Failed"})
            except Exception as e:
                self._send_body(500, {"error": "Internal Server Error"})

    return EmailPostHandler

import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json
def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, body, content_type="text/plain; charset=utf-8"):
            if isinstance(body, str):
                body_bytes = body.encode("utf-8")
            else:
                body_bytes = body
            self.send_response(status_code)
            self.send_header("content-type", content_type)
            self.send_header("content-length", str(len(body_bytes)))
            self.end_headers()
            self.wfile.write(body_bytes)

        def do_POST(self):
            try:
                length = int(self.headers.get("content-length", "0"))
            except ValueError:
                length = 0

            raw = self.rfile.read(length)
            body_text = raw.decode("utf-8", errors="replace")

            try:
                data = json.loads(body_text)
            except json.JSONDecodeError:
                self._send_response(400, "Bad Request")
                return

            try:
                if not isinstance(data, dict):
                    raise ValueError("Invalid payload type")
                subject = data["subject"]
                message = data["message"]
                to_addr = data["to"]
                if subject is None or message is None or to_addr is None:
                    raise ValueError("Missing required fields")
            except (KeyError, ValueError):
                self._send_response(400, "Bad Request")
                return

            msg = MIMEText(str(message))
            msg["Subject"] = str(subject)
            msg["From"] = smtp_username
            msg["To"] = str(to_addr)

            try:
                server = smtplib.SMTP(smtp_server, smtp_port, timeout=15)
                try:
                    server.ehlo()
                    try:
                        server.starttls()
                        server.ehlo()
                    except smtplib.SMTPException:
                        pass
                    server.login(smtp_username, smtp_password)
                    server.sendmail(smtp_username, [str(to_addr)], msg.as_string())
                finally:
                    try:
                        server.quit()
                    except Exception:
                        pass
            except smtplib.SMTPAuthenticationError:
                self._send_response(535, "Authentication Failed")
                return
            except Exception:
                self._send_response(500, "Internal Server Error")
                return

            self._send_response(200, "OK")

    return EmailPostHandler

