import pandas as pd
import json
import numpy as np
import matplotlib.pyplot as plt
COLUMNS = ['email', 'list']
def task_func(json_file):
    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except Exception:
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None

    records = []
    if isinstance(data, dict):
        for email, lst in data.items():
            records.append({'email': email, 'list': lst})
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict) and 'email' in item and 'list' in item:
                records.append({'email': item.get('email'), 'list': item.get('list')})

    if not records:
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None

    df = pd.DataFrame.from_records(records)
    for col in COLUMNS:
        if col not in df.columns:
            df[col] = None
    df = df[COLUMNS].copy()

    def compute_sum_mean(x):
        if not isinstance(x, (list, tuple, np.ndarray)):
            return (np.nan, np.nan)
        arr = np.array(x, dtype=float) if len(x) else np.array([], dtype=float)
        s = float(np.sum(arr)) if arr.size else 0.0
        m = float(np.mean(arr)) if arr.size else np.nan
        return (s, m)

    sums_means = df['list'].apply(compute_sum_mean)
    df['sum'] = sums_means.apply(lambda t: t[0])
    df['mean'] = sums_means.apply(lambda t: t[1])

    if df.empty:
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None

    x = np.arange(len(df))
    width = 0.4
    fig, ax = plt.subplots()
    ax.bar(x - width / 2, df['sum'].to_numpy(dtype=float), width, label='sum')
    ax.bar(x + width / 2, df['mean'].to_numpy(dtype=float), width, label='mean')
    ax.set_xticks(x)
    ax.set_xticklabels(df['email'].astype(str).tolist(), rotation=45, ha='right')
    ax.set_xlabel('email')
    ax.legend()

    return df[['email', 'list', 'sum', 'mean']], ax

