import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return {"data": None, "value_counts": Counter()}

    email_pattern = re.compile(r'(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b')

    def process(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                pv = process(v)
                if pv is not None:
                    out[k] = pv
            return out
        if isinstance(obj, list):
            out = []
            for item in obj:
                pi = process(item)
                if pi is not None:
                    out.append(pi)
            return out
        if isinstance(obj, str):
            return email_pattern.sub(REPLACE_NONE, obj)
        return obj

    processed = process(data)

    def collect_values(obj, acc):
        if obj is None:
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, acc)
            return
        if isinstance(obj, list):
            for item in obj:
                collect_values(item, acc)
            return
        try:
            acc.append(obj)
        except Exception:
            return

    values = []
    collect_values(processed, values)
    value_counts = Counter(values)

    return {"data": processed, "value_counts": value_counts}

