def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError("Malformed JSON data") from e

    if data is None or data == "" or data == [] or data == {}:
        raise ValueError("Empty JSON data")

    rows = []

    def coerce_population(v):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("Non-numeric population")
        if v < 0:
            raise ValueError("Negative population")
        if isinstance(v, float):
            return int(math.floor(v))
        return int(v)

    if isinstance(data, dict):
        if all(isinstance(k, str) for k in data.keys()):
            for country, pop in data.items():
                if not isinstance(country, str):
                    raise ValueError("Non-string country name")
                rows.append((country, coerce_population(pop)))
        else:
            raise ValueError("Invalid JSON structure")
    elif isinstance(data, list):
        if len(data) == 0:
            raise ValueError("Empty JSON data")
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Invalid JSON structure")
            if "Country" in item and "Population" in item:
                country = item["Country"]
                pop = item["Population"]
            elif "country" in item and "population" in item:
                country = item["country"]
                pop = item["population"]
            else:
                raise ValueError("Invalid JSON structure")
            if not isinstance(country, str):
                raise ValueError("Non-string country name")
            rows.append((country, coerce_population(pop)))
    else:
        raise ValueError("Invalid JSON structure")

    if len(rows) == 0:
