import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("Empty JSON data")

    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError("Corrupted JSON data") from e

    cur = data
    for key in key_path:
        if isinstance(cur, dict):
            if key not in cur:
                raise KeyError(key)
            cur = cur[key]
        elif isinstance(cur, (list, tuple)):
            idx = key
            if isinstance(idx, str):
                if idx.isdigit() or (idx.startswith("-") and idx[1:].isdigit()):
                    idx = int(idx)
            if not isinstance(idx, int):
                raise KeyError(key)
            if idx < 0 or idx >= len(cur):
                raise KeyError(key)
            cur = cur[idx]
        else:
            raise KeyError(key)

    values = []

    def add_numeric(x):
        if isinstance(x, (np.integer, int, np.floating, float)) and np.isfinite(x):
            values.append(float(x))

    if cur is None:
        pass
    elif isinstance(cur, (np.integer, int, np.floating, float)):
        add_numeric(cur)
    elif isinstance(cur, dict):
        for v in cur.values():
            add_numeric(v)
    elif isinstance(cur, (list, tuple, np.ndarray, pd.Series)):
        for v in list(cur):
            add_numeric(v)
    elif isinstance(cur, str):
        s = cur.strip()
        if not s:
            raise ValueError("Empty data string at target path")
        import re
        tokens = re.findall(r"[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?", s)
        for t in tokens:
            try:
                add_numeric(float(t))
            except Exception:
                pass
    else:
        try:
            add_numeric(float(cur))
        except Exception:
            pass

    if len(values) == 0:
        raise ValueError("No numeric data found at target path")

    df = pd.DataFrame({"values": values})
    fig, ax = plt.subplots()
    sns.boxplot(y="values", data=df, ax=ax)
    ax.set_ylabel("values")
    return fig

