import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    data = json.loads(json_data)

    cur = data
    for part in [p for p in str(data_key).split(".") if p != ""]:
        if isinstance(cur, list):
            try:
                idx = int(part)
            except Exception as e:
                raise KeyError(part) from e
            if idx < 0 or idx >= len(cur):
                raise KeyError(part)
            cur = cur[idx]
        elif isinstance(cur, dict):
            if part not in cur:
                raise KeyError(part)
            cur = cur[part]
        else:
            raise KeyError(part)

    if cur is None:
        values = []
    elif isinstance(cur, (list, tuple, pd.Series)):
        values = list(cur)
    else:
        values = [cur]

    original = pd.Series(values, dtype="float64")

    if original.size == 0:
        return original, None, None

    scaler = MinMaxScaler()
    normalized_arr = scaler.fit_transform(original.to_numpy(dtype="float64").reshape(-1, 1)).reshape(-1)
    normalized = pd.Series(normalized_arr, dtype="float64")

    _, ax = plt.subplots()
    ax.plot(original.index, original.values, label="Original Data")
    ax.plot(normalized.index, normalized.values, label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()

    return original, normalized, ax
